// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testRegression_property() public {
        address user = address(0x1234);
        address to = address(0x5678);

        vm.deal(user, 2 wei);
        vm.prank(user);
        c.deposit{value: 2 wei}();

        vm.prank(address(this));
        c.migrateTo(to);

        uint256 toBalance = address(to).balance;
        assertTrue(toBalance == 2 wei);
    }
}
